import datetime
# Assume values['v1'] and values['v2'] are lists of rates for each issue date in March 1977
# values['v1_labels'] and values['v2_labels'] are the corresponding issue date strings (e.g., '1977-Mar-01')
# We need to compute the absolute gap for each date and find the date with the smallest gap.
# Since cohort retrieval returns flat lists, we assume the labels are the same for both cohorts (same dates).
if len(values['v1']) == 0 or len(values['v2']) == 0:
    result = "Data not found"
else:
    gaps = [abs(v1 - v2) for v1, v2 in zip(values['v1'], values['v2'])]
    min_gap_index = gaps.index(min(gaps))
    date_str = values['v1_labels'][min_gap_index]
    # Convert to U.S. long date format: Month Day, Year (e.g., March 15, 1977)
    # Parse the date string; it might be in various formats (e.g., '1977-Mar-01', 'March 1, 1977', 'Mar 1, 1977').
    # We'll try common parsers.
    try:
        # If it's already in long format, use as is.
        dt = datetime.datetime.strptime(date_str, '%B %d, %Y')
    except ValueError:
        try:
            dt = datetime.datetime.strptime(date_str, '%b %d, %Y')
        except ValueError:
            try:
