import numpy as np

# values['v1'] is list of 9 annual expenditures in millions of dollars
vals = values['v1']
if len(vals) != 9:
    raise ValueError(f'Expected 9 values, got {len(vals)}')

# Compute year-to-year log growth rates: log(v_t / v_{t-1})
growth_rates = []
for i in range(1, len(vals)):
    if vals[i-1] == 0:
        growth_rates.append(0.0)
    else:
        growth_rates.append(np.log(vals[i] / vals[i-1]))

# Coefficient of variation = population std dev / mean
mean_gr = np.mean(growth_rates)
std_gr = np.std(growth_rates, ddof=0)  # population standard deviation
if mean_gr == 0:
    cv = 0.0
else:
    cv = std_gr / mean_gr

result = round(cv, 2)  # round to nearest hundredth

